.page {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  min-width: 0;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
  margin-bottom: 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin: 0 0 3px;
}

.subtitle {
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
  margin: 0 0 16px;
  max-width: 560px;
}

/* Estado E2EE: en el MVP las claves viven en memoria de sesión y no hay
   passphrase, así que no se ofrece el botón «Introducir frase de seguridad». */
.e2eeBar {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--bw-signal-green);
  margin-bottom: 14px;
  padding: 6px 10px;
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  border-radius: 5px;
  width: fit-content;
}

.e2eeBar i {
  font-size: 12px;
}

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}

.searchWrap {
  position: relative;
  flex: 1;
  max-width: 300px;
  min-width: 220px;
}

.searchWrap i {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  font-size: 13px;
  color: var(--bw-deep-steel);
  outline: none;
  font-family: inherit;
  background: var(--bw-surface-mist);
  transition: border-color 0.15s;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.newContactWrap {
  display: flex;
  align-items: center;
  gap: 8px;
}

.primaryBtn {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  color: var(--bw-surface-mist);
  font-size: 13px;
  font-weight: 500;
  font-family: inherit;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  cursor: not-allowed;
  opacity: 0.55;
}

.primaryBtn:disabled {
  cursor: not-allowed;
}

/* Motivo visible de tener el botón «Nuevo contacto» apagado: DIR-01 no se
   entrega en el MVP. El botón existe para que la pantalla no prometa una
   acción que no lleva a ningún sitio, y el motivo lo dice al lado. */
.scopeNote {
  font-size: 11px;
  line-height: 1.4;
  color: var(--bw-steel-mist);
  max-width: 230px;
}

.pagInfo {
  font-size: 12px;
  color: var(--bw-input-placeholder);
  margin-left: auto;
  white-space: nowrap;
}

.loading {
  padding: 28px 18px;
  font-size: 13px;
  color: var(--bw-steel-mist);
  text-align: center;
}

/* El aviso de error interrumpe, por eso lleva role="alert"; el estado de
   carga no lo lleva. */
.errorBox {
  padding: 12px 14px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 5px;
  background: var(--bw-sensitive-bg);
  color: var(--bw-sensitive-text);
  font-size: 13px;
  line-height: 1.5;
}

/* ── Paginación ──────────────────────────────────────────────────────────── */

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn,
.pageCtrl {
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-surface-mist);
  font-size: 12px;
  color: var(--bw-ink-steel);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  transition:
    border-color 0.12s,
    color 0.12s;
}

.pageBtn:hover:not(:disabled),
.pageCtrl:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtn:disabled,
.pageCtrl:disabled {
  cursor: default;
  opacity: 0.55;
}

.pageActive {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
}

.pageActive:hover:not(:disabled) {
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
}

