import { useEffect, useState, type FormEvent } from 'react';
import type { MemberProfile } from '../../lib/session';
import { fetchThreadPage, pageCount, type ThreadPage } from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /**
   * Firma pública cableada desde App.tsx. MSG-02 no está en el alcance: abrir
   * un hilo no lleva a ningún sitio, así que esta prop se recibe y se ignora.
   */
  onOpenThread?: (threadId: string) => void;
}

/**
 * Convierte el fallo de `fetchThreadPage` en texto para humanos.
 *
 * PostgREST no lanza `Error`: rechaza con un objeto plano `{ code, message }`.
 * `String(e)` daría "[object Object]" y `e.message` sería `undefined`; hay que
 * pescar `code` y `message` cuando existan y enseñarlos junto a la frase.
 */
function errorDetail(err: unknown): string {
  if (err instanceof Error) return err.message;
  if (err && typeof err === 'object') {
    const { code, message } = err as { code?: unknown; message?: unknown };
    const bits: string[] = [];
    if (typeof code === 'string' && code !== '') bits.push(code);
    if (typeof message === 'string' && message !== '') bits.push(message);
    if (bits.length > 0) return bits.join(' · ');
  }
  if (typeof err === 'string' && err !== '') return err;
  return 'Error desconocido';
}

export function Messages({ profile, now, onOpenThread }: MessagesProps) {
  // La prop existe por contrato de firma pública; MSG-02 no se construyó.
  void onOpenThread;

  const [searchInput, setSearchInput] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<ThreadPage | null>(null);
  const [error, setError] = useState<unknown>(null);

  useEffect(() => {
    let alive = true;
    setLoading(true);
    setError(null);
    fetchThreadPage({ orgId: profile.orgId, search, page })
      .then((result) => {
        if (!alive) return;
        setData(result);
        setLoading(false);
      })
      .catch((cause: unknown) => {
        if (!alive) return;
        setError(cause);
        setLoading(false);
      });
    return () => {
      alive = false;
    };
  }, [profile.orgId, search, page]);

  const handleSearchSubmit = (event: FormEvent) => {
    event.preventDefault();
    setSearch(searchInput.trim());
    setPage(1);
  };

  const total = data?.total ?? 0;
  const pages = pageCount(total);

  return (
    <div className={styles.page}>
      <div className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</div>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a
        extremo.
      </p>

      <div className={styles.e2eeBar}>
        <i className="ti ti-lock" aria-hidden="true" />
        E2EE activo · claves de sesión en memoria
      </div>

      <div className={styles.actionsBar}>
        <form className={styles.searchWrap} role="search" onSubmit={handleSearchSubmit}>
          <i className="ti ti-search" aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            value={searchInput}
            onChange={(event) => setSearchInput(event.target.value)}
          />
        </form>

        <div className={styles.newContactWrap}>
          <button type="button" className={styles.primaryBtn} disabled>
            <i className="ti ti-address-book" aria-hidden="true" />
            Nuevo contacto
          </button>
          <span className={styles.scopeNote} data-testid="directorio-scope">
            El Directorio (DIR-01) queda fuera del MVP.
          </span>
        </div>

        <span className={styles.pagInfo} data-testid="pag-info">
          {total} {total === 1 ? 'hilo' : 'hilos'} · Página {page} de {pages}
        </span>
      </div>

      {loading ? (
        <div className={styles.loading} role="status">
          Cargando hilos…
        </div>
      ) : error ? (
        <div className={styles.errorBox} role="alert">
          No se pudieron cargar los hilos: {errorDetail(error)}.
        </div>
      ) : data ? (
        <>
          <ThreadList threads={data.threads} now={now} onOpen={() => {}} />

          <div className={styles.pagination}>
            <button
              type="button"
              className={styles.pageCtrl}
              aria-label="Página anterior"
              disabled={page <= 1}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
            >
              ‹
            </button>

            {Array.from({ length: pages }, (_, i) => i + 1).map((n) => (
              <button
                key={n}
                type="button"
                className={n === page ? `${styles.pageBtn} ${styles.pageActive}` : styles.pageBtn}
                aria-current={n === page ? 'page' : undefined}
                disabled={n === page}
                onClick={() => setPage(n)}
              >
                {n}
              </button>
            ))}

            <button
              type="button"
              className={styles.pageCtrl}
              aria-label="Página siguiente"
              disabled={page >= pages}
              onClick={() => setPage((p) => Math.min(pages, p + 1))}
            >
              ›
            </button>
          </div>
        </>
      ) : null}
    </div>
  );
}

