/* El fondo de tarjeta blanco del HTML aprobado no tiene token propio en el
   sistema de diseño (§1): el más cercano para una superficie clara elevada es
   --bw-surface-mist (#F8F9FB), y de él salen también los controles blancos. */

.list {
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row {
  border-bottom: 1px solid var(--bw-divider-mist);
}

.row:last-child {
  border-bottom: none;
}

.rowBtn {
  width: 100%;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 14px 18px;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  font-family: inherit;
  transition: background 0.1s;
}

.row:hover {
  background: var(--bw-row-hover-tint);
}

.rowMain {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.rowTop {
  display: flex;
  align-items: center;
  gap: 8px;
}

.rowBottom {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.orgName {
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.countryBadge {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
}

.preview {
  font-size: 12px;
  color: var(--bw-steel-mist);
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Vista previa: solo metadatos en claro de thread_items (tipo y referencia).
   Nunca contenido descifrado, y si no hay último elemento se dice «Sin
   actividad» sin inventar puntos suspensivos de una passphrase que no existe. */

.stateBadge {
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
  flex-shrink: 0;
}

.neutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}

.info {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border: 1px solid var(--bw-chip-active-border);
}

.warn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

.success {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}

.closed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-hint-steel);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

.timestamp {
  flex-shrink: 0;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-hint-steel);
  white-space: nowrap;
  padding-top: 2px;
}

/* ── Estado vacío ──────────────────────────────────────────────────────────
   Va en un contenedor aparte, nunca dentro del <ul>: con cero hilos el
   documento no puede tener ningún listitem. */
.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 40px 20px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  text-align: center;
}

.emptyMsg {
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
  max-width: 420px;
  margin: 0;
}

.primaryBtn {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  color: var(--bw-surface-mist);
  font-size: 13px;
  font-weight: 500;
  font-family: inherit;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  cursor: not-allowed;
  opacity: 0.55;
}

.scopeNote {
  font-size: 11px;
  line-height: 1.4;
  color: var(--bw-steel-mist);
  max-width: 340px;
}

