import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Clase CSS por cada tono de estado.
 *
 * Con `noUncheckedIndexedAccess`, las propiedades de `styles` se tipan
 * `string | undefined`: una clase que falte en el módulo deja la fila sin
 * adorno en vez de escribir la palabra "undefined" en el atributo.
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.neutral,
  info: styles.info,
  warn: styles.warn,
  success: styles.success,
  closed: styles.closed,
};

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  onOpen: (id: string) => void;
}

/**
 * Lista de hilos de MSG-01. Presentacional: pinta las filas en el orden en que
 * las recibe (el orden viene del servidor) y avisa con el ID del hilo al abrir.
 */
export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyMsg}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras
          organizaciones.
        </p>
        {/* DIR-01 no está entre las pantallas del MVP: el botón se ve pero está
            apagado, y el motivo es visible al lado. Sin esto sería un botón que
            parece pulsable y no lleva a ningún sitio. */}
        <button type="button" className={styles.primaryBtn} disabled>
          Ir al Directorio
        </button>
        <p className={styles.scopeNote}>El Directorio queda fuera del MVP.</p>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => {
        const tone = TONE_CLASS[stateTone(thread.state)] ?? '';
        return (
          // El <li> conserva su rol listitem: la pulsación vive en el <button>
          // de dentro, nunca en un role encima del <li>.
          <li key={thread.id} className={styles.row}>
            <button
              type="button"
              className={styles.rowBtn}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.rowMain}>
                <span className={styles.rowTop}>
                  <span className={styles.orgName}>{thread.counterpartyName}</span>
                  {thread.counterpartyCountry !== '' && (
                    <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
                  )}
                </span>
                <span className={styles.rowBottom}>
                  <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
                  <span className={`${styles.stateBadge} ${tone}`}>{thread.state}</span>
                </span>
              </span>
              <span className={styles.timestamp}>{relativeTime(thread.lastItemAt, now)}</span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
